    {
      "service": "ts-seat-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' AS period, count(*) AS n FROM abnormal_traces WHERE service_name='ts-order-other-service' AND span_name='POST /api/v1/orderOtherService/orderOther/tickets' UNION ALL SELECT 'normal', count(*) FROM normal_traces WHERE service_name='ts-order-other-service' AND span_name='POST /api/v1/orderOtherService/orderOther/tickets'",
          "claim": "Order-other /tickets server spans vanish in the incident (0 vs 1268 normal); requests never reach it."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_status_code, attr_http_response_status_code, count(*) n, round(avg(duration/1e6),0) avg_ms, round(min(duration/1e6),0) min_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name='POST' AND attr_span_kind='Client' GROUP BY ALL",
          "claim": "Seat's outgoing POST calls: 16 fail after ~130s with no response code; 50 succeed but take ~4s on average."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(avg(duration/1e6),1) avg_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Server' AND span_name LIKE '%left_tickets%' GROUP BY ALL",
          "claim": "Seat left_tickets server spans are slow (avg ~4s, max ~130s) and 16 return 500, versus ~16ms normal."
        }
      ]
    },
    {
      "service": "ts-travel2-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'abnormal' p, avg(value) avg_pending, max(value) max_pending FROM abnormal_metrics_sum WHERE metric='db.client.connections.pending_requests' AND service_name='ts-travel2-service' UNION ALL SELECT 'normal', avg(value), max(value) FROM normal_metrics_sum WHERE metric='db.client.connections.pending_requests' AND service_name='ts-travel2-service'",
          "claim": "Travel2 DB connection pool shows pending requests (up to 3) during the incident and none normally."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(avg(duration/1e6),0) avg_ms, round(max(duration/1e6),0) max_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name='SELECT Trip' AND duration>1e9 GROUP BY ALL",
          "claim": "Travel2 'SELECT Trip' spans take 7-29s while the child JDBC query runs in about 1ms, i.e. waiting for a connection."
        }
      ]
    }
